// === collision.js — Racing Game ===
// Car-to-car and car-to-track collision detection and response.
// Uses AABB broad phase + SAT narrow phase for rotated-rect car bodies.
// Off-track detection with graduated friction penalties.

// ─── Constants (extend R.CONFIG) ───────────────────────────────────────────

R.CONFIG.CAR_WIDTH            = R.CONFIG.CAR_WIDTH            || 40;
R.CONFIG.CAR_HEIGHT           = R.CONFIG.CAR_HEIGHT           || 70;
R.CONFIG.COLLISION_DAMPING    = R.CONFIG.COLLISION_DAMPING    || 0.7;
R.CONFIG.COLLISION_SPEED_LOSS = R.CONFIG.COLLISION_SPEED_LOSS || 0.85;
R.CONFIG.OFFROAD_FRICTION     = R.CONFIG.OFFROAD_FRICTION     || 0.92;
R.CONFIG.OFFROAD_DEEP_PENALTY = R.CONFIG.OFFROAD_DEEP_PENALTY || 0.80;
R.CONFIG.OFFROAD_DEEP_THRESH  = R.CONFIG.OFFROAD_DEEP_THRESH  || 50;
R.CONFIG.MIN_SPEED            = R.CONFIG.MIN_SPEED            || 0.5;
R.CONFIG.MIN_COLLISION_SPEED  = R.CONFIG.MIN_COLLISION_SPEED  || 2.0;
R.CONFIG.SPARK_SPEED_THRESH   = R.CONFIG.SPARK_SPEED_THRESH   || 4.0;
R.CONFIG.MAX_SIMULTANEOUS     = R.CONFIG.MAX_SIMULTANEOUS     || 8;

// ─── Helpers ────────────────────────────────────────────────────────────────

/**
 * Rotate a point (px, py) around origin (ox, oy) by angle (radians).
 * Returns { x, y }.
 */
R._rotatePoint = function(px, py, ox, oy, angle) {
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const dx = px - ox;
  const dy = py - oy;
  return {
    x: ox + dx * cos - dy * sin,
    y: oy + dx * sin + dy * cos
  };
};

/**
 * Project a polygon of points onto an axis.
 * Returns { min, max }.
 */
R._projectPolygon = function(points, axisX, axisY) {
  let min = Infinity;
  let max = -Infinity;
  for (let i = 0; i < points.length; i++) {
    const dot = points[i].x * axisX + points[i].y * axisY;
    if (dot < min) min = dot;
    if (dot > max) max = dot;
  }
  return { min, max };
};

/**
 * Get the 4 corner points of a car as a rotated rectangle.
 * Car origin (x, y) is center of the rectangle.
 */
R._getCarCorners = function(car) {
  const hw = R.CONFIG.CAR_WIDTH * 0.5;
  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
  const cx = car.x;
  const cy = car.y;
  const angle = car.angle || 0;

  // Local corners before rotation
  const local = [
    { x: -hw, y: -hh },
    { x:  hw, y: -hh },
    { x:  hw, y:  hh },
    { x: -hw, y:  hh }
  ];

  const corners = [];
  for (let i = 0; i < 4; i++) {
    corners.push(R._rotatePoint(
      cx + local[i].x,
      cy + local[i].y,
      cx, cy, angle
    ));
  }
  return corners;
};

/**
 * Get the 4 edge normals (axes) of a polygon for SAT.
 * Each normal is perpendicular to an edge, normalized.
 */
R._getNormals = function(corners) {
  const normals = [];
  for (let i = 0; i < corners.length; i++) {
    const j = (i + 1) % corners.length;
    const edgeX = corners[j].x - corners[i].x;
    const edgeY = corners[j].y - corners[i].y;
    const len = Math.sqrt(edgeX * edgeX + edgeY * edgeY);
    if (len < 0.0001) continue; // degenerate edge
    // Perpendicular: (-edgeY, edgeX)
    normals.push({ x: -edgeY / len, y: edgeX / len });
  }
  return normals;
};

/**
 * Compute overlap amount on a given axis between two projections.
 * Returns number (positive if overlapping, negative if separated).
 */
R._overlapOnAxis = function(projA, projB) {
  const overlap = Math.min(projA.max, projB.max) - Math.max(projA.min, projB.min);
  return overlap;
};

// ─── AABB ───────────────────────────────────────────────────────────────────

/**
 * Compute axis-aligned bounding box for a car.
 * Accounts for the car's rotation by taking the max extent of the rectangle.
 *
 * @param {Object} car — Car object with { x, y, angle }
 * @returns {{ minX: number, maxX: number, minY: number, maxY: number }}
 */
R.carAABB = function(car) {
  const hw = R.CONFIG.CAR_WIDTH * 0.5;
  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
  const angle = car.angle || 0;

  // Max extent of rotated half-width/height (worst-case circle bounds)
  const absCos = Math.abs(Math.cos(angle));
  const absSin = Math.abs(Math.sin(angle));
  const radiusX = hw * absCos + hh * absSin;
  const radiusY = hw * absSin + hh * absCos;

  return {
    minX: car.x - radiusX,
    maxX: car.x + radiusX,
    minY: car.y - radiusY,
    maxY: car.y + radiusY
  };
};

/**
 * Test if two AABBs overlap.
 */
R._aabbOverlap = function(a, b) {
  return (
    a.minX < b.maxX &&
    a.maxX > b.minX &&
    a.minY < b.maxY &&
    a.maxY > b.minY
  );
};

// ─── Car-to-Car Collision (SAT) ─────────────────────────────────────────────

/**
 * Detailed collision detection between two cars using Separating Axis Theorem.
 * Each car is a 40x70 rotated rectangle.
 *
 * @param {Object} carA — First car
 * @param {Object} carB — Second car
 * @returns {{ hit: boolean, overlapX: number, overlapY: number, depth: number } | null}
 *   Returns null if no collision, otherwise collision data.
 */
R.checkCarToCar = function(carA, carB) {
  // --- Broad phase: AABB ---
  const aabbA = R.carAABB(carA);
  const aabbB = R.carAABB(carB);
  if (!R._aabbOverlap(aabbA, aabbB)) {
    return null;
  }

  // --- Narrow phase: SAT ---
  const cornersA = R._getCarCorners(carA);
  const cornersB = R._getCarCorners(carB);

  // Gather all separating axes (normals from both polygons)
  const normalsA = R._getNormals(cornersA);
  const normalsB = R._getNormals(cornersB);
  const axes = normalsA.concat(normalsB);

  let minOverlap = Infinity;
  let minAxisX = 0;
  let minAxisY = 0;

  for (let i = 0; i < axes.length; i++) {
    const ax = axes[i].x;
    const ay = axes[i].y;

    const projA = R._projectPolygon(cornersA, ax, ay);
    const projB = R._projectPolygon(cornersB, ax, ay);

    const overlap = R._overlapOnAxis(projA, projB);

    if (overlap <= 0) {
      // Separating axis found — no collision
      return null;
    }

    if (overlap < minOverlap) {
      minOverlap = overlap;
      minAxisX = ax;
      minAxisY = ay;
    }
  }

  // No separating axis found — collision confirmed
  // The minimum overlap axis is the collision normal (approximately)
  return {
    hit: true,
    overlapX: minAxisX * minOverlap,
    overlapY: minAxisY * minOverlap,
    depth: minOverlap
  };
};

// ─── Collision Resolution ───────────────────────────────────────────────────

/**
 * Resolve a collision between two cars: push apart and adjust velocities.
 *
 * Pushing apart:
 *   - Each car receives 50% of the overlap correction, unless one is stationary.
 *   - A stationary car (speed < MIN_SPEED) gets pushed more (70%) while the
 *     moving car takes 30%.
 *
 * Impulse:
 *   - Relative velocity along collision normal
 *   - Apply COLLISION_DAMPING to reduce rebound
 *   - Faster car transfers some speed to slower car
 *   - Both lose COLLISION_SPEED_LOSS factor
 *
 * @param {Object} carA — First car
 * @param {Object} carB — Second car
 * @param {{ overlapX: number, overlapY: number, depth: number }} overlap — Collision data from checkCarToCar
 */
R.resolveCollision = function(carA, carB, overlap) {
  const depth = overlap.depth;
  if (depth <= 0) return;

  // --- Determine which car is stationary ---
  const speedA = Math.abs(carA.speed || 0);
  const speedB = Math.abs(carB.speed || 0);
  const aStationary = speedA < R.CONFIG.MIN_SPEED;
  const bStationary = speedB < R.CONFIG.MIN_SPEED;

  let pushRatioA, pushRatioB;
  if (aStationary && !bStationary) {
    pushRatioA = 0.7;
    pushRatioB = 0.3;
  } else if (bStationary && !aStationary) {
    pushRatioA = 0.3;
    pushRatioB = 0.7;
  } else {
    pushRatioA = 0.5;
    pushRatioB = 0.5;
  }

  // --- Push cars apart ---
  const pushX = overlap.overlapX;
  const pushY = overlap.overlapY;

  carA.x -= pushX * pushRatioA;
  carA.y -= pushY * pushRatioA;
  carB.x += pushX * pushRatioB;
  carB.y += pushY * pushRatioB;

  // --- Velocity impulse ---
  // Collision normal (direction from A to B)
  const nx = overlap.overlapX / (depth || 0.001);
  const ny = overlap.overlapY / (depth || 0.001);

  // Decompose car velocities into components along collision normal
  // Car velocity is in direction of car.angle
  const vAx = Math.cos(carA.angle || 0) * (carA.speed || 0);
  const vAy = Math.sin(carA.angle || 0) * (carA.speed || 0);
  const vBx = Math.cos(carB.angle || 0) * (carB.speed || 0);
  const vBy = Math.sin(carB.angle || 0) * (carB.speed || 0);

  // Relative velocity along normal
  const relVx = vAx - vBx;
  const relVy = vAy - vBy;
  const relVelN = relVx * nx + relVy * ny;

  // Only resolve if cars are approaching each other
  if (relVelN > 0) {
    // Impulse magnitude
    const impulse = relVelN * R.CONFIG.COLLISION_DAMPING;

    // Convert impulse back to speed adjustments
    // For simplicity, adjust scalar speed proportionally
    const speedLoss = impulse * (1 - R.CONFIG.COLLISION_DAMPING);

    // Apply speed changes: slower car gains, faster car loses
    const totalMass = 2; // equal mass
    if (!aStationary && !bStationary) {
      // Equal mass elastic-ish collision with damping
      const avgSpeed = (carA.speed + carB.speed) / 2;
      carA.speed = avgSpeed - (carA.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
      carB.speed = avgSpeed - (carB.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
    } else if (aStationary) {
      // B hits stationary A
      carB.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
      carA.speed = carB.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
    } else if (bStationary) {
      // A hits stationary B
      carA.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
      carB.speed = carA.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
    }

    // Both lose some speed from collision
    carA.speed *= R.CONFIG.COLLISION_DAMPING;
    carB.speed *= R.CONFIG.COLLISION_DAMPING;

    // Clamp to zero for very small speeds
    if (Math.abs(carA.speed) < R.CONFIG.MIN_SPEED * 0.5) carA.speed = 0;
    if (Math.abs(carB.speed) < R.CONFIG.MIN_SPEED * 0.5) carB.speed = 0;
  }
};

// ─── Boundary Checking ──────────────────────────────────────────────────────

/**
 * Check if a car is off the track and apply penalties.
 *
 * - Uses R.isOnTrack(car.x, car.z) to determine track position.
 * - If off track: applies off-road friction, spawns dust, applies
 *   aggressive speed reduction when deep off track.
 * - If on track after being off: no action needed (normal physics apply).
 *
 * @param {Object} car — Car object
 * @param {number} dt — Delta time in seconds
 */
R.checkCarToBoundary = function(car, dt) {
  // Guard: isOnTrack must exist
  if (typeof R.isOnTrack !== 'function') return;

  const onTrack = R.isOnTrack(car.x, car.z !== undefined ? car.z : 0);

  if (onTrack) {
    // Car is on track — reset any off-track state
    car._offTrack = false;
    car._offTrackDepth = 0;
    return;
  }

  // Car is off track
  car._offTrack = true;

  // Estimate how far off track (simple radial distance from nearest track edge)
  // We approximate: if isOnTrack returns false, car is at least at the boundary.
  // For deep-off-track detection, we check a slight offset.
  const testOffset = R.CONFIG.OFFROAD_DEEP_THRESH;
  let deepOff = false;

  if (typeof R.isOnTrack === 'function') {
    // Try a point further out to gauge depth
    const onTrackNear = R.isOnTrack(
      car.x + (car.x > 0 ? -testOffset : testOffset),
      car.z !== undefined ? car.z : 0
    );
    deepOff = !onTrackNear;
  } else {
    deepOff = false;
  }

  car._offTrackDepth = deepOff ? R.CONFIG.OFFROAD_DEEP_THRESH + 1 : 30;

  // --- Apply off-road friction ---
  const friction = deepOff
    ? R.CONFIG.OFFROAD_DEEP_PENALTY
    : R.CONFIG.OFFROAD_FRICTION;

  car.speed *= friction;

  // Aggressive speed scrubbing for fast cars deep off track
  if (deepOff && Math.abs(car.speed) > 3) {
    car.speed *= R.CONFIG.OFFROAD_DEEP_PENALTY;
  }

  // Clamp tiny speeds to zero
  if (Math.abs(car.speed) < R.CONFIG.MIN_SPEED * 0.3) {
    car.speed = 0;
  }

  // --- Visual feedback: dust particles ---
  if (typeof R.spawnDust === 'function' && Math.abs(car.speed) > 0.5) {
    const dustCount = deepOff ? 4 : 2;
    R.spawnDust(car.x, car.y, dustCount);
  }

  // --- Off-track steering reduction (optional realism) ---
  // Slight steering penalty off-road — car is harder to control
  if (car.steerAngle && Math.abs(car.speed) > 2) {
    // Reduce effective steering by friction factor (handled by physics module typically)
    // Here we just note it — actual implementation may be in handling module
    car._offRoadSteerScale = 0.6;
  }
};

// ─── Per-Frame Collision Check ──────────────────────────────────────────────

/**
 * Main collision detection entry point. Called each frame during 'racing' phase.
 *
 * Process:
 *   1. Gather all active cars (player + AI).
 *   2. Broad-phase AABB culling for all pairs.
 *   3. Narrow-phase SAT for close pairs.
 *   4. Sort collisions by depth (deepest first).
 *   5. Resolve each collision (push apart + impulse).
 *   6. Re-check boundary for all cars involved in collisions.
 *   7. Spawn spark effects and play sounds for significant collisions.
 */
R.checkCollisions = function() {
  if (R.state.phase !== 'racing') return;

  // --- Gather all active cars ---
  const cars = [];

  // Player car
  if (R.playerCar) {
    cars.push(R.playerCar);
  }

  // AI cars
  if (R.aiCars && R.aiCars.length > 0) {
    for (let i = 0; i < R.aiCars.length; i++) {
      cars.push(R.aiCars[i]);
    }
  }

  if (cars.length < 2) return;

  // --- Broad phase: collect candidate pairs ---
  const candidates = [];

  // Pre-compute all AABBs
  const aabbs = [];
  for (let i = 0; i < cars.length; i++) {
    aabbs.push(R.carAABB(cars[i]));
  }

  for (let i = 0; i < cars.length; i++) {
    for (let j = i + 1; j < cars.length; j++) {
      if (R._aabbOverlap(aabbs[i], aabbs[j])) {
        candidates.push({ a: cars[i], b: cars[j], idxA: i, idxB: j });
      }
    }
  }

  if (candidates.length === 0) {
    // No AABB overlaps — also check boundaries for all cars
    for (let i = 0; i < cars.length; i++) {
      R.checkCarToBoundary(cars[i], 0.016); // approximate dt
    }
    return;
  }

  // --- Narrow phase: SAT for each candidate ---
  /** @type {{ carA: Object, carB: Object, overlap: Object, depth: number }[]} */
  const collisions = [];

  for (let k = 0; k < candidates.length; k++) {
    const { a, b } = candidates[k];
    const result = R.checkCarToCar(a, b);
    if (result && result.hit) {
      collisions.push({
        carA: a,
        carB: b,
        overlap: result,
        depth: result.depth
      });
    }
  }

  // --- Sort by depth (deepest first) ---
  collisions.sort(function(c1, c2) {
    return c2.depth - c1.depth;
  });

  // --- Limit simultaneous collision resolutions ---
  const maxResolve = Math.min(collisions.length, R.CONFIG.MAX_SIMULTANEOUS);
  const resolvedCars = {}; // Track which cars have been resolved this frame

  for (let k = 0; k < maxResolve; k++) {
    const col = collisions[k];

    // Check if these cars have already been resolved too many times
    const keyA = col.carA._id || 'player';
    const keyB = col.carB._id || ('ai_' + R.aiCars.indexOf(col.carB));
    resolvedCars[keyA] = (resolvedCars[keyA] || 0) + 1;
    resolvedCars[keyB] = (resolvedCars[keyB] || 0) + 1;

    // Limit per-car resolutions to prevent jitter
    if (resolvedCars[keyA] > 3 || resolvedCars[keyB] > 3) continue;

    // --- Determine collision intensity ---
    const speedA = Math.abs(col.carA.speed || 0);
    const speedB = Math.abs(col.carB.speed || 0);
    const relSpeed = Math.abs(speedA - speedB);
    const avgSpeed = (speedA + speedB) / 2;

    // --- Resolve the collision ---
    R.resolveCollision(col.carA, col.carB, col.overlap);

    // --- Visual and audio feedback ---
    const midpointX = (col.carA.x + col.carB.x) / 2;
    const midpointY = (col.carA.y + col.carB.y) / 2;

    if (avgSpeed > R.CONFIG.SPARK_SPEED_THRESH) {
      // Significant collision: sparks
      const intensity = Math.min(avgSpeed / 20, 1); // 0..1 range
      if (typeof R.spawnSparks === 'function') {
        R.spawnSparks(midpointX, midpointY, intensity);
      }
      if (typeof R.playSound === 'function') {
        R.playSound('crash', intensity);
      }
    } else if (avgSpeed > R.CONFIG.MIN_COLLISION_SPEED) {
      // Minor collision: lighter sparks, quieter sound
      const intensity = avgSpeed / R.CONFIG.SPARK_SPEED_THRESH * 0.5;
      if (typeof R.spawnSparks === 'function') {
        R.spawnSparks(midpointX, midpointY, intensity);
      }
      if (typeof R.playSound === 'function') {
        R.playSound('crash', intensity * 0.3);
      }
    }
    // Very slow collision: no effects (just nudging)
  }

  // --- Boundary re-check for cars involved in collisions ---
  // Cars may have been pushed off track during resolution
  const boundaryChecked = {}; // prevent double-checking same car
  for (let k = 0; k < maxResolve; k++) {
    const col = collisions[k];

    const keyA = col.carA._id || 'player';
    const keyB = col.carB._id || ('ai_' + R.aiCars.indexOf(col.carB));

    if (!boundaryChecked[keyA]) {
      R.checkCarToBoundary(col.carA, 0.016);
      boundaryChecked[keyA] = true;
    }
    if (!boundaryChecked[keyB]) {
      R.checkCarToBoundary(col.carB, 0.016);
      boundaryChecked[keyB] = true;
    }
  }

  // --- Boundary check for non-colliding cars ---
  const collidedIndices = {};
  for (let k = 0; k < maxResolve; k++) {
    collidedIndices[candidates.indexOf({ a: collisions[k].carA, b: collisions[k].carB })] = true;
  }

  for (let i = 0; i < cars.length; i++) {
    const carKey = cars[i]._id || (cars[i] === R.playerCar ? 'player' : 'ai_' + R.aiCars.indexOf(cars[i]));
    if (!boundaryChecked[carKey]) {
      R.checkCarToBoundary(cars[i], 0.016);
      boundaryChecked[carKey] = true;
    }
  }
};

// ─── Utility: Get collision info for debugging / HUD ────────────────────────

/**
 * Returns a string describing the last collision for debugging.
 * Populated during checkCollisions.
 */
R._lastCollisionInfo = null;

/**
 * Get the number of active collisions detected this frame.
 * For debugging and performance monitoring.
 */
R._collisionCountThisFrame = 0;

// Override checkCollisions to track stats
(function() {
  const _origCheckCollisions = R.checkCollisions;
  R.checkCollisions = function() {
    R._collisionCountThisFrame = 0;
    R._lastCollisionInfo = null;

    if (R.state.phase !== 'racing') return;

    // Gather cars
    const cars = [];
    if (R.playerCar) cars.push(R.playerCar);
    if (R.aiCars && R.aiCars.length > 0) {
      for (let i = 0; i < R.aiCars.length; i++) cars.push(R.aiCars[i]);
    }
    if (cars.length < 2) {
      // Still check boundaries
      for (let i = 0; i < cars.length; i++) {
        R.checkCarToBoundary(cars[i], 0.016);
      }
      return;
    }

    // AABB culling
    const aabbs = [];
    for (let i = 0; i < cars.length; i++) {
      aabbs.push(R.carAABB(cars[i]));
    }

    const candidates = [];
    for (let i = 0; i < cars.length; i++) {
      for (let j = i + 1; j < cars.length; j++) {
        if (R._aabbOverlap(aabbs[i], aabbs[j])) {
          candidates.push({ a: cars[i], b: cars[j], idxA: i, idxB: j });
        }
      }
    }

    if (candidates.length === 0) {
      for (let i = 0; i < cars.length; i++) {
        R.checkCarToBoundary(cars[i], 0.016);
      }
      return;
    }

    // SAT narrow phase
    const collisions = [];
    for (let k = 0; k < candidates.length; k++) {
      const { a, b } = candidates[k];
      const result = R.checkCarToCar(a, b);
      if (result && result.hit) {
        collisions.push({
          carA: a,
          carB: b,
          overlap: result,
          depth: result.depth
        });
      }
    }

    R._collisionCountThisFrame = collisions.length;

    // Sort deepest first
    collisions.sort(function(c1, c2) {
      return c2.depth - c1.depth;
    });

    const maxResolve = Math.min(collisions.length, R.CONFIG.MAX_SIMULTANEOUS);
    const resolvedCars = {};

    for (let k = 0; k < maxResolve; k++) {
      const col = collisions[k];

      const keyA = col.carA._id || 'player';
      const keyB = col.carB._id || ('ai_' + R.aiCars.indexOf(col.carB));

      resolvedCars[keyA] = (resolvedCars[keyA] || 0) + 1;
      resolvedCars[keyB] = (resolvedCars[keyB] || 0) + 1;

      if (resolvedCars[keyA] > 3 || resolvedCars[keyB] > 3) continue;

      const speedA = Math.abs(col.carA.speed || 0);
      const speedB = Math.abs(col.carB.speed || 0);
      const avgSpeed = (speedA + speedB) / 2;

      R.resolveCollision(col.carA, col.carB, col.overlap);

      const midpointX = (col.carA.x + col.carB.x) / 2;
      const midpointY = (col.carA.y + col.carB.y) / 2;

      if (avgSpeed > R.CONFIG.SPARK_SPEED_THRESH) {
        const intensity = Math.min(avgSpeed / 20, 1);
        if (typeof R.spawnSparks === 'function') {
          R.spawnSparks(midpointX, midpointY, intensity);
        }
        if (typeof R.playSound === 'function') {
          R.playSound('crash', intensity);
        }
      } else if (avgSpeed > R.CONFIG.MIN_COLLISION_SPEED) {
        const intensity = avgSpeed / R.CONFIG.SPARK_SPEED_THRESH * 0.5;
        if (typeof R.spawnSparks === 'function') {
          R.spawnSparks(midpointX, midpointY, intensity);
        }
        if (typeof R.playSound === 'function') {
          R.playSound('crash', intensity * 0.3);
        }
      }

      // Record last collision
      R._lastCollisionInfo = {
        carA: keyA,
        carB: keyB,
        depth: col.depth,
        avgSpeed: avgSpeed
      };
    }

    // Boundary checks for all cars
    const boundaryChecked = {};
    for (let k = 0; k < maxResolve; k++) {
      const col = collisions[k];
      const keyA = col.carA._id || 'player';
      const keyB = col.carB._id || ('ai_' + R.aiCars.indexOf(col.carB));

      if (!boundaryChecked[keyA]) {
        R.checkCarToBoundary(col.carA, 0.016);
        boundaryChecked[keyA] = true;
      }
      if (!boundaryChecked[keyB]) {
        R.checkCarToBoundary(col.carB, 0.016);
        boundaryChecked[keyB] = true;
      }
    }
    for (let i = 0; i < cars.length; i++) {
      const carKey = cars[i]._id || (cars[i] === R.playerCar ? 'player' : 'ai_' + R.aiCars.indexOf(cars[i]));
      if (!boundaryChecked[carKey]) {
        R.checkCarToBoundary(cars[i], 0.016);
        boundaryChecked[carKey] = true;
      }
    }
  };
})();

// ─── Exports ────────────────────────────────────────────────────────────────
// Exported (attached to window.R):
//   R.checkCollisions()        — per-frame collision check (entry point)
//   R.checkCarToCar(carA, carB) — SAT collision test, returns {hit, overlapX, overlapY, depth} | null
//   R.checkCarToBoundary(car)   — off-track penalty check
//   R.resolveCollision(carA, carB, overlap) — push apart + impulse
//   R.carAABB(car)             — AABB for broad-phase, returns {minX, maxX, minY, maxY}
//
// Internal helpers (on R for testability):
//   R._rotatePoint(px, py, ox, oy, angle) — rotate point around origin
//   R._projectPolygon(points, axisX, axisY)
//   R._getCarCorners(car)
//   R._getNormals(corners)
//   R._overlapOnAxis(projA, projB)
//   R._aabbOverlap(a, b)
//
// Debug/metrics:
//   R._lastCollisionInfo  — details of last resolved collision this frame
//   R._collisionCountThisFrame — number of active collisions detected

