1	// === collision.js — Racing Game ===
2	// Car-to-car and car-to-track collision detection and response.
3	// Uses AABB broad phase + SAT narrow phase for rotated-rect car bodies.
4	// Off-track detection with graduated friction penalties.
5	
6	// ─── Constants (extend R.CONFIG) ───────────────────────────────────────────
7	
8	R.CONFIG.CAR_WIDTH            = R.CONFIG.CAR_WIDTH            || 40;
9	R.CONFIG.CAR_HEIGHT           = R.CONFIG.CAR_HEIGHT           || 70;
10	R.CONFIG.COLLISION_DAMPING    = R.CONFIG.COLLISION_DAMPING    || 0.7;
11	R.CONFIG.COLLISION_SPEED_LOSS = R.CONFIG.COLLISION_SPEED_LOSS || 0.85;
12	R.CONFIG.OFFROAD_FRICTION     = R.CONFIG.OFFROAD_FRICTION     || 0.92;
13	R.CONFIG.OFFROAD_DEEP_PENALTY = R.CONFIG.OFFROAD_DEEP_PENALTY || 0.80;
14	R.CONFIG.OFFROAD_DEEP_THRESH  = R.CONFIG.OFFROAD_DEEP_THRESH  || 50;
15	R.CONFIG.MIN_SPEED            = R.CONFIG.MIN_SPEED            || 0.5;
16	R.CONFIG.MIN_COLLISION_SPEED  = R.CONFIG.MIN_COLLISION_SPEED  || 2.0;
17	R.CONFIG.SPARK_SPEED_THRESH   = R.CONFIG.SPARK_SPEED_THRESH   || 4.0;
18	R.CONFIG.MAX_SIMULTANEOUS     = R.CONFIG.MAX_SIMULTANEOUS     || 8;
19	
20	// ─── Helpers ────────────────────────────────────────────────────────────────
21	
22	/**
23	 * Rotate a point (px, py) around origin (ox, oy) by angle (radians).
24	 * Returns { x, y }.
25	 */
26	R._rotatePoint = function(px, py, ox, oy, angle) {
27	  const cos = Math.cos(angle);
28	  const sin = Math.sin(angle);
29	  const dx = px - ox;
30	  const dy = py - oy;
31	  return {
32	    x: ox + dx * cos - dy * sin,
33	    y: oy + dx * sin + dy * cos
34	  };
35	};
36	
37	/**
38	 * Project a polygon of points onto an axis.
39	 * Returns { min, max }.
40	 */
41	R._projectPolygon = function(points, axisX, axisY) {
42	  let min = Infinity;
43	  let max = -Infinity;
44	  for (let i = 0; i < points.length; i++) {
45	    const dot = points[i].x * axisX + points[i].y * axisY;
46	    if (dot < min) min = dot;
47	    if (dot > max) max = dot;
48	  }
49	  return { min, max };
50	};
51	
52	/**
53	 * Get the 4 corner points of a car as a rotated rectangle.
54	 * Car origin (x, y) is center of the rectangle.
55	 */
56	R._getCarCorners = function(car) {
57	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
58	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
59	  const cx = car.x;
60	  const cy = car.y;
61	  const angle = car.angle || 0;
62	
63	  // Local corners before rotation
64	  const local = [
65	    { x: -hw, y: -hh },
66	    { x:  hw, y: -hh },
67	    { x:  hw, y:  hh },
68	    { x: -hw, y:  hh }
69	  ];
70	
71	  const corners = [];
72	  for (let i = 0; i < 4; i++) {
73	    corners.push(R._rotatePoint(
74	      cx + local[i].x,
75	      cy + local[i].y,
76	      cx, cy, angle
77	    ));
78	  }
79	  return corners;
80	};
81	
82	/**
83	 * Get the 4 edge normals (axes) of a polygon for SAT.
84	 * Each normal is perpendicular to an edge, normalized.
85	 */
86	R._getNormals = function(corners) {
87	  const normals = [];
88	  for (let i = 0; i < corners.length; i++) {
89	    const j = (i + 1) % corners.length;
90	    const edgeX = corners[j].x - corners[i].x;
91	    const edgeY = corners[j].y - corners[i].y;
92	    const len = Math.sqrt(edgeX * edgeX + edgeY * edgeY);
93	    if (len < 0.0001) continue; // degenerate edge
94	    // Perpendicular: (-edgeY, edgeX)
95	    normals.push({ x: -edgeY / len, y: edgeX / len });
96	  }
97	  return normals;
98	};
99	
100	/**
101	 * Compute overlap amount on a given axis between two projections.
102	 * Returns number (positive if overlapping, negative if separated).
103	 */
104	R._overlapOnAxis = function(projA, projB) {
105	  const overlap = Math.min(projA.max, projB.max) - Math.max(projA.min, projB.min);
106	  return overlap;
107	};
108	
109	// ─── AABB ───────────────────────────────────────────────────────────────────
110	
111	/**
112	 * Compute axis-aligned bounding box for a car.
113	 * Accounts for the car's rotation by taking the max extent of the rectangle.
114	 *
115	 * @param {Object} car — Car object with { x, y, angle }
116	 * @returns {{ minX: number, maxX: number, minY: number, maxY: number }}
117	 */
118	R.carAABB = function(car) {
119	  const hw = R.CONFIG.CAR_WIDTH * 0.5;
120	  const hh = R.CONFIG.CAR_HEIGHT * 0.5;
121	  const angle = car.angle || 0;
122	
123	  // Max extent of rotated half-width/height (worst-case circle bounds)
124	  const absCos = Math.abs(Math.cos(angle));
125	  const absSin = Math.abs(Math.sin(angle));
126	  const radiusX = hw * absCos + hh * absSin;
127	  const radiusY = hw * absSin + hh * absCos;
128	
129	  return {
130	    minX: car.x - radiusX,
131	    maxX: car.x + radiusX,
132	    minY: car.y - radiusY,
133	    maxY: car.y + radiusY
134	  };
135	};
136	
137	/**
138	 * Test if two AABBs overlap.
139	 */
140	R._aabbOverlap = function(a, b) {
141	  return (
142	    a.minX < b.maxX &&
143	    a.maxX > b.minX &&
144	    a.minY < b.maxY &&
145	    a.maxY > b.minY
146	  );
147	};
148	
149	// ─── Car-to-Car Collision (SAT) ─────────────────────────────────────────────
150	
151	/**
152	 * Detailed collision detection between two cars using Separating Axis Theorem.
153	 * Each car is a 40x70 rotated rectangle.
154	 *
155	 * @param {Object} carA — First car
156	 * @param {Object} carB — Second car
157	 * @returns {{ hit: boolean, overlapX: number, overlapY: number, depth: number } | null}
158	 *   Returns null if no collision, otherwise collision data.
159	 */
160	R.checkCarToCar = function(carA, carB) {
161	  // --- Broad phase: AABB ---
162	  const aabbA = R.carAABB(carA);
163	  const aabbB = R.carAABB(carB);
164	  if (!R._aabbOverlap(aabbA, aabbB)) {
165	    return null;
166	  }
167	
168	  // --- Narrow phase: SAT ---
169	  const cornersA = R._getCarCorners(carA);
170	  const cornersB = R._getCarCorners(carB);
171	
172	  // Gather all separating axes (normals from both polygons)
173	  const normalsA = R._getNormals(cornersA);
174	  const normalsB = R._getNormals(cornersB);
175	  const axes = normalsA.concat(normalsB);
176	
177	  let minOverlap = Infinity;
178	  let minAxisX = 0;
179	  let minAxisY = 0;
180	
181	  for (let i = 0; i < axes.length; i++) {
182	    const ax = axes[i].x;
183	    const ay = axes[i].y;
184	
185	    const projA = R._projectPolygon(cornersA, ax, ay);
186	    const projB = R._projectPolygon(cornersB, ax, ay);
187	
188	    const overlap = R._overlapOnAxis(projA, projB);
189	
190	    if (overlap <= 0) {
191	      // Separating axis found — no collision
192	      return null;
193	    }
194	
195	    if (overlap < minOverlap) {
196	      minOverlap = overlap;
197	      minAxisX = ax;
198	      minAxisY = ay;
199	    }
200	  }
201	
202	  // No separating axis found — collision confirmed
203	  // The minimum overlap axis is the collision normal (approximately)
204	  return {
205	    hit: true,
206	    overlapX: minAxisX * minOverlap,
207	    overlapY: minAxisY * minOverlap,
208	    depth: minOverlap
209	  };
210	};
211	
212	// ─── Collision Resolution ───────────────────────────────────────────────────
213	
214	/**
215	 * Resolve a collision between two cars: push apart and adjust velocities.
216	 *
217	 * Pushing apart:
218	 *   - Each car receives 50% of the overlap correction, unless one is stationary.
219	 *   - A stationary car (speed < MIN_SPEED) gets pushed more (70%) while the
220	 *     moving car takes 30%.
221	 *
222	 * Impulse:
223	 *   - Relative velocity along collision normal
224	 *   - Apply COLLISION_DAMPING to reduce rebound
225	 *   - Faster car transfers some speed to slower car
226	 *   - Both lose COLLISION_SPEED_LOSS factor
227	 *
228	 * @param {Object} carA — First car
229	 * @param {Object} carB — Second car
230	 * @param {{ overlapX: number, overlapY: number, depth: number }} overlap — Collision data from checkCarToCar
231	 */
232	R.resolveCollision = function(carA, carB, overlap) {
233	  const depth = overlap.depth;
234	  if (depth <= 0) return;
235	
236	  // --- Determine which car is stationary ---
237	  const speedA = Math.abs(carA.speed || 0);
238	  const speedB = Math.abs(carB.speed || 0);
239	  const aStationary = speedA < R.CONFIG.MIN_SPEED;
240	  const bStationary = speedB < R.CONFIG.MIN_SPEED;
241	
242	  let pushRatioA, pushRatioB;
243	  if (aStationary && !bStationary) {
244	    pushRatioA = 0.7;
245	    pushRatioB = 0.3;
246	  } else if (bStationary && !aStationary) {
247	    pushRatioA = 0.3;
248	    pushRatioB = 0.7;
249	  } else {
250	    pushRatioA = 0.5;
251	    pushRatioB = 0.5;
252	  }
253	
254	  // --- Push cars apart ---
255	  const pushX = overlap.overlapX;
256	  const pushY = overlap.overlapY;
257	
258	  carA.x -= pushX * pushRatioA;
259	  carA.y -= pushY * pushRatioA;
260	  carB.x += pushX * pushRatioB;
261	  carB.y += pushY * pushRatioB;
262	
263	  // --- Velocity impulse ---
264	  // Collision normal (direction from A to B)
265	  const nx = overlap.overlapX / (depth || 0.001);
266	  const ny = overlap.overlapY / (depth || 0.001);
267	
268	  // Decompose car velocities into components along collision normal
269	  // Car velocity is in direction of car.angle
270	  const vAx = Math.cos(carA.angle || 0) * (carA.speed || 0);
271	  const vAy = Math.sin(carA.angle || 0) * (carA.speed || 0);
272	  const vBx = Math.cos(carB.angle || 0) * (carB.speed || 0);
273	  const vBy = Math.sin(carB.angle || 0) * (carB.speed || 0);
274	
275	  // Relative velocity along normal
276	  const relVx = vAx - vBx;
277	  const relVy = vAy - vBy;
278	  const relVelN = relVx * nx + relVy * ny;
279	
280	  // Only resolve if cars are approaching each other
281	  if (relVelN > 0) {
282	    // Impulse magnitude
283	    const impulse = relVelN * R.CONFIG.COLLISION_DAMPING;
284	
285	    // Convert impulse back to speed adjustments
286	    // For simplicity, adjust scalar speed proportionally
287	    const speedLoss = impulse * (1 - R.CONFIG.COLLISION_DAMPING);
288	
289	    // Apply speed changes: slower car gains, faster car loses
290	    const totalMass = 2; // equal mass
291	    if (!aStationary && !bStationary) {
292	      // Equal mass elastic-ish collision with damping
293	      const avgSpeed = (carA.speed + carB.speed) / 2;
294	      carA.speed = avgSpeed - (carA.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
295	      carB.speed = avgSpeed - (carB.speed - avgSpeed) * R.CONFIG.COLLISION_DAMPING;
296	    } else if (aStationary) {
297	      // B hits stationary A
298	      carB.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
299	      carA.speed = carB.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
300	    } else if (bStationary) {
301	      // A hits stationary B
302	      carA.speed *= R.CONFIG.COLLISION_SPEED_LOSS;
303	      carB.speed = carA.speed * (1 - R.CONFIG.COLLISION_DAMPING) * 0.3;
304	    }
305	
306	    // Both lose some speed from collision
307	    carA.speed *= R.CONFIG.COLLISION_DAMPING;
308	    carB.speed *= R.CONFIG.COLLISION_DAMPING;
309	
310	    // Clamp to zero for very small speeds
311	    if (Math.abs(carA.speed) < R.CONFIG.MIN_SPEED * 0.5) carA.speed = 0;
312	    if (Math.abs(carB.speed) < R.CONFIG.MIN_SPEED * 0.5) carB.speed = 0;
313	  }
314	};
315	
316	// ─── Boundary Checking ──────────────────────────────────────────────────────
317	
318	/**
319	 * Check if a car is off the track and apply penalties.
320	 *
321	 * - Uses R.isOnTrack(car.x, car.z) to determine track position.
322	 * - If off track: applies off-road friction, spawns dust, applies
323	 *   aggressive speed reduction when deep off track.
324	 * - If on track after being off: no action needed (normal physics apply).
325	 *
326	 * @param {Object} car — Car object
327	 * @param {number} dt — Delta time in seconds
328	 */
329	R.checkCarToBoundary = function(car, dt) {
330	  // Guard: isOnTrack must exist
331	  if (typeof R.isOnTrack !== 'function') return;
332	
333	  const onTrack = R.isOnTrack(car.x, car.z !== undefined ? car.z : 0);
334	
335	  if (onTrack) {
336	    // Car is on track — reset any off-track state
337	    car._offTrack = false;
338	    car._offTrackDepth = 0;
339	    return;
340	  }
341	
342	  // Car is off track
343	  car._offTrack = true;
344	
345	  // Estimate how far off track (simple radial distance from nearest track edge)
346	  // We approximate: if isOnTrack returns false, car is at least at the boundary.
347	  // For deep-off-track detection, we check a slight offset.
348	  const testOffset = R.CONFIG.OFFROAD_DEEP_THRESH;
349	  let deepOff = false;
350	
351	  if (typeof R.isOnTrack === 'function') {
352	    // Try a point further out to gauge depth
353	    const onTrackNear = R.isOnTrack(
354	      car.x + (car.x > 0 ? -testOffset : testOffset),
355	      car.z !== undefined ? car.z : 0
356	    );
357	    deepOff = !onTrackNear;
358	  } else {
359	    deepOff = false;
360	  }
361	
362	  car._offTrackDepth = deepOff ? R.CONFIG.OFFROAD_DEEP_THRESH + 1 : 30;
363	
364	  // --- Apply off-road friction ---
365	  const friction = deepOff
366	    ? R.CONFIG.OFFROAD_DEEP_PENALTY
367	    : R.CONFIG.OFFROAD_FRICTION;
368	
369	  car.speed *= friction;
370	
371	  // Aggressive speed scrubbing for fast cars deep off track
372	  if (deepOff && Math.abs(car.speed) > 3) {
373	    car.speed *= R.CONFIG.OFFROAD_DEEP_PENALTY;
374	  }
375	
376	  // Clamp tiny speeds to zero
377	  if (Math.abs(car.speed) < R.CONFIG.MIN_SPEED * 0.3) {
378	    car.speed = 0;
379	  }
380	
381	  // --- Visual feedback: dust particles ---
382	  if (typeof R.spawnDust === 'function' && Math.abs(car.speed) > 0.5) {
383	    const dustCount = deepOff ? 4 : 2;
384	    R.spawnDust(car.x, car.y, dustCount);
385	  }
386	
387	  // --- Off-track steering reduction (optional realism) ---
388	  // Slight steering penalty off-road — car is harder to control
389	  if (car.steerAngle && Math.abs(car.speed) > 2) {
390	    // Reduce effective steering by friction factor (handled by physics module typically)
391	    // Here we just note it — actual implementation may be in handling module
392	    car._offRoadSteerScale = 0.6;
393	  }
394	};
395	
396	// ─── Per-Frame Collision Check ──────────────────────────────────────────────
397	
398	/**
399	 * Main collision detection entry point. Called each frame during 'racing' phase.
400	 *
401	 * Process:
402	 *   1. Gather all active cars (player + AI).
403	 *   2. Broad-phase AABB culling for all pairs.
404	 *   3. Narrow-phase SAT for close pairs.
405	 *   4. Sort collisions by depth (deepest first).
406	 *   5. Resolve each collision (push apart + impulse).
407	 *   6. Re-check boundary for all cars involved in collisions.
408	 *   7. Spawn spark effects and play sounds for significant collisions.
409	 */
410	R.checkCollisions = function() {
411	  if (R.state.phase !== 'racing') return;
412	
413	  // --- Gather all active cars ---
414	  const cars = [];
415	
416	  // Player car
417	  if (R.playerCar) {
418	    cars.push(R.playerCar);
419	  }
420	
421	  // AI cars
422	  if (R.aiCars && R.aiCars.length > 0) {
423	    for (let i = 0; i < R.aiCars.length; i++) {
424	      cars.push(R.aiCars[i]);
425	    }
426	  }
427	
428	  if (cars.length < 2) return;
429	
430	  // --- Broad phase: collect candidate pairs ---
431	  const candidates = [];
432	
433	  // Pre-compute all AABBs
434	  const aabbs = [];
435	  for (let i = 0; i < cars.length; i++) {
436	    aabbs.push(R.carAABB(cars[i]));
437	  }
438	
439	  for (let i = 0; i < cars.length; i++) {
440	    for (let j = i + 1; j < cars.length; j++) {
441	      if (R._aabbOverlap(aabbs[i], aabbs[j])) {
442	        candidates.push({ a: cars[i], b: cars[j], idxA: i, idxB: j });
443	      }
444	    }
445	  }
446	
447	  if (candidates.length === 0) {
448	    // No AABB overlaps — also check boundaries for all cars
449	    for (let i = 0; i < cars.length; i++) {
450	      R.checkCarToBoundary(cars[i], 0.016); // approximate dt
451	    }
452	    return;
453	  }
454	
455	  // --- Narrow phase: SAT for each candidate ---
456	  /** @type {{ carA: Object, carB: Object, overlap: Object, depth: number }[]} */
457	  const collisions = [];
458	
459	  for (let k = 0; k < candidates.length; k++) {
460	    const { a, b } = candidates[k];
461	    const result = R.checkCarToCar(a, b);
462	    if (result && result.hit) {
463	      collisions.push({
464	        carA: a,
465	        carB: b,
466	        overlap: result,
467	        depth: result.depth
468	      });
469	    }
470	  }
471	
472	  // --- Sort by depth (deepest first) ---
473	  collisions.sort(function(c1, c2) {
474	    return c2.depth - c1.depth;
475	  });
476	
477	  // --- Limit simultaneous collision resolutions ---
478	  const maxResolve = Math.min(collisions.length, R.CONFIG.MAX_SIMULTANEOUS);
479	  const resolvedCars = {}; // Track which cars have been resolved this frame
480	
481	  for (let k = 0; k < maxResolve; k++) {
482	    const col = collisions[k];
483	
484	    // Check if these cars have already been resolved too many times
485	    const keyA = col.carA._id || 'player';
486	    const keyB = col.carB._id || ('ai_' + R.aiCars.indexOf(col.carB));
487	    resolvedCars[keyA] = (resolvedCars[keyA] || 0) + 1;
488	    resolvedCars[keyB] = (resolvedCars[keyB] || 0) + 1;
489	
490	    // Limit per-car resolutions to prevent jitter
491	    if (resolvedCars[keyA] > 3 || resolvedCars[keyB] > 3) continue;
492	
493	    // --- Determine collision intensity ---
494	    const speedA = Math.abs(col.carA.speed || 0);
495	    const speedB = Math.abs(col.carB.speed || 0);
496	    const relSpeed = Math.abs(speedA - speedB);
497	    const avgSpeed = (speedA + speedB) / 2;
498	
499	    // --- Resolve the collision ---
500	    R.resolveCollision(col.carA, col.carB, col.overlap);
501	
502	    // --- Visual and audio feedback ---
503	    const midpointX = (col.carA.x + col.carB.x) / 2;
504	    const midpointY = (col.carA.y + col.carB.y) / 2;
505	
506	    if (avgSpeed > R.CONFIG.SPARK_SPEED_THRESH) {
507	      // Significant collision: sparks
508	      const intensity = Math.min(avgSpeed / 20, 1); // 0..1 range
509	      if (typeof R.spawnSparks === 'function') {
510	        R.spawnSparks(midpointX, midpointY, intensity);
511	      }
512	      if (typeof R.playSound === 'function') {
513	        R.playSound('crash', intensity);
514	      }
515	    } else if (avgSpeed > R.CONFIG.MIN_COLLISION_SPEED) {
516	      // Minor collision: lighter sparks, quieter sound
517	      const intensity = avgSpeed / R.CONFIG.SPARK_SPEED_THRESH * 0.5;
518	      if (typeof R.spawnSparks === 'function') {
519	        R.spawnSparks(midpointX, midpointY, intensity);
520	      }
521	      if (typeof R.playSound === 'function') {
522	        R.playSound('crash', intensity * 0.3);
523	      }
524	    }
525	    // Very slow collision: no effects (just nudging)
526	  }
527	
528	  // --- Boundary re-check for cars involved in collisions ---
529	  // Cars may have been pushed off track during resolution
530	  const boundaryChecked = {}; // prevent double-checking same car
531	  for (let k = 0; k < maxResolve; k++) {
532	    const col = collisions[k];
533	
534	    const keyA = col.carA._id || 'player';
535	    const keyB = col.carB._id || ('ai_' + R.aiCars.indexOf(col.carB));
536	
537	    if (!boundaryChecked[keyA]) {
538	      R.checkCarToBoundary(col.carA, 0.016);
539	      boundaryChecked[keyA] = true;
540	    }
